.page-complex {
    height: 100%;
}

.empty {
    padding: 20px;
}

.el-select::v-deep {
    .el-select__tags {
        // 解决多个tag卡片溢出隐藏问题
        overflow: hidden;
        display: -webkit-box;
        -webkit-line-clamp: 1;
        -webkit-box-orient: vertical;

        .el-tag {
            // 注意这个inline-block 对卡片溢出隐藏很重要
            display: inline-block;

            // 解决单个tag文字过长溢出隐藏问题
            .el-select__tags-text {
                display: inline-block;
                max-width: 90px;
                overflow: hidden;
                text-overflow: ellipsis;
                white-space: nowrap;
            }
            .el-icon-close {
                top: -6px;
                right: -4px;
            }
        }
    }
}
